// Input comes from the webhook body: { message_id?, sender?, text }
const b = $json.body || {};
const text = typeof b.text === 'string' ? b.text.trim().slice(0, 5000) : '';
const sender = typeof b.sender === 'string' ? b.sender.trim().toLowerCase() : 'unknown';
const message_id = b.message_id != null ? String(b.message_id).trim() : '';
const hasContent = /[\p{L}\p{N}]/u.test(text); // rejects '', whitespace, '!!!???'
if (!hasContent) {
  return [{ json: { valid: false, error: 'text is required and must contain letters or digits' } }];
}
// Duplicate key: explicit message_id wins, otherwise sender + normalised text
const dedupe_source = message_id ? 'id:' + message_id : 'txt:' + sender + '|' + text.toLowerCase().replace(/\s+/g, ' ');
return [{ json: { valid: true, text, sender, message_id, dedupe_source } }];

// Validates the model JSON. Invalid -> retry once (loop back to AI: Classify), then fall back to human review.
const cfg = $('Config (edit prompts & settings here)').first().json;
const cats = cfg.categories.split(',').map(s => s.trim());
const base = $('Valid Input?').first().json;
const attempt = $runIndex + 1;
const raw = $json.choices?.[0]?.message?.content;

function parse(content) {
  if (typeof content !== 'string') return null;
  const m = content.replace(/```(?:json)?/gi, '').match(/\{[\s\S]*\}/);
  if (!m) return null;
  let o; try { o = JSON.parse(m[0]); } catch (e) { return null; }
  let c = Number(o.confidence);
  if (c > 1 && c <= 100) c = c / 100; // tolerate 85 meaning 85%
  if (!cats.includes(o.category) || !Number.isFinite(c) || c < 0 || c > 1 || typeof o.needs_human_review !== 'boolean') return null;
  return { category: o.category, confidence: c, needs_human_review: o.needs_human_review, reason: String(o.reason || '').slice(0, 300) };
}

const ok = parse(raw);
if (ok) return [{ json: { ...base, ...ok, ai_attempts: attempt, retry: false } }];
if (attempt < 2) return [{ json: { ...base, retry: true } }];
return [{ json: { ...base, category: 'General Question', confidence: 0, needs_human_review: true,
  reason: 'AI output invalid after retry (' + ($json.error ? 'LLM call failed: ' + String($json.error.message || $json.error).slice(0, 150) : 'malformed JSON') + '); needs human triage',
  ai_attempts: attempt, retry: false } }];

// Alert rules live here: notify if confidence < threshold, category is Refund Request, or human review is flagged.
const cfg = $('Config (edit prompts & settings here)').first().json;
const c = $('Parse & Validate Classification').first().json;
let draft = $json.choices?.[0]?.message?.content;
draft = typeof draft === 'string' ? draft.trim() : '';
const reasons = [];
if (c.confidence < cfg.confidenceThreshold) reasons.push('low confidence (' + c.confidence + ' < ' + cfg.confidenceThreshold + ')');
if (c.category === 'Refund Request') reasons.push('refund request');
if (c.needs_human_review) reasons.push('flagged for human review');
if (!draft) reasons.push('draft generation failed');
return [{ json: { ...c, draft_response: draft, notify_reasons: reasons.join('; '), should_notify: reasons.length > 0 } }];
